#ifndef TEST_VECTORS_H
#define TEST_VECTORS_H

#include <stddef.h>
#include <stdint.h>

/** One SHA-256 reference message and its expected digest. */
typedef struct {
    const uint8_t *message;  /**< Input bytes. */
    size_t length;           /**< Input length. */
    const uint8_t *digest;   /**< Expected 32-byte digest. */
} test_sha_vector_t;

/** Private scalar of the host-test key (not the development key). */
extern const uint8_t test_signing_privkey[32];

/** 16-byte body signed by tools/mkimage.py. */
extern const uint8_t test_python_body[16];

/** Header for test_python_body, signed with security counter 7. */
extern const uint8_t test_python_header[256];

/** SHA-256 reference vectors. */
extern const test_sha_vector_t test_sha_vectors[];

/** Number of entries in @ref test_sha_vectors. */
extern const size_t test_sha_vector_count;

#endif /* TEST_VECTORS_H */
